// The owner's own logo picture is the brand mark everywhere.
//
// One picture (a black rounded plate with a white speech bubble and a blue
// arrow) is cut into every place the mark is drawn: the launcher icon, the
// in-app brand mark, the notification icon, the web logo, the favicon and
// the PWA icon. The files are generated by scripts/make-brand-assets.py, and
// this case pins the result: the same mark, the right sizes, and the
// adaptive icon's background is the plate's own black rather than the old
// amber.

import { readFileSync, existsSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { inflateSync } from "node:zlib";

const root = new URL("../../", import.meta.url).pathname;
const read = (path) => readFileSync(join(root, path));
const lines = [];
const check = (name, cond, detail) =>
  lines.push(`  ${cond ? "OK     " : "BROKEN "}  ${name}${detail ? `  -> ${detail}` : ""}`);

/** The size of a PNG, straight out of its IHDR chunk. */
const pngSize = (buf) => ({
  width: buf.readUInt32BE(16),
  height: buf.readUInt32BE(20),
});

/**
 * The pixels of an 8-bit RGBA PNG. Node has no image decoder, and this case
 * has to look at the mark itself (the plate is black, the corners are
 * transparent), so the few lines of PNG reading live here: the IDAT chunks
 * are inflated and the five scanline filters are undone.
 */
const pngPixels = (buf) => {
  const width = buf.readUInt32BE(16);
  const height = buf.readUInt32BE(20);
  const colorType = buf[25];
  if (buf[24] !== 8 || colorType !== 6) throw new Error("expected an 8-bit RGBA PNG");
  const idat = [];
  let at = 8;
  while (at < buf.length) {
    const length = buf.readUInt32BE(at);
    const type = buf.toString("ascii", at + 4, at + 8);
    if (type === "IDAT") idat.push(buf.subarray(at + 8, at + 8 + length));
    at += 12 + length;
  }
  const raw = inflateSync(Buffer.concat(idat));
  const stride = width * 4;
  const out = Buffer.alloc(stride * height);
  let pos = 0;
  for (let y = 0; y < height; y++) {
    const filter = raw[pos++];
    const line = raw.subarray(pos, pos + stride);
    pos += stride;
    const prev = y > 0 ? out.subarray((y - 1) * stride, y * stride) : null;
    const cur = out.subarray(y * stride, (y + 1) * stride);
    for (let i = 0; i < stride; i++) {
      const a = i >= 4 ? cur[i - 4] : 0;
      const b = prev ? prev[i] : 0;
      const c = prev && i >= 4 ? prev[i - 4] : 0;
      const x = line[i];
      if (filter === 0) cur[i] = x;
      else if (filter === 1) cur[i] = (x + a) & 0xff;
      else if (filter === 2) cur[i] = (x + b) & 0xff;
      else if (filter === 3) cur[i] = (x + ((a + b) >> 1)) & 0xff;
      else if (filter === 4) {
        const p = a + b - c;
        const pa = Math.abs(p - a);
        const pb = Math.abs(p - b);
        const pc = Math.abs(p - c);
        const pick = pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
        cur[i] = (x + pick) & 0xff;
      } else throw new Error(`unknown PNG filter ${filter}`);
    }
  }
  return { width, height, data: out };
};

const logo = read("web/public/logo.png");
const logoSize = pngSize(logo);
check(
  "the web logo is a 192x192 PNG",
  logoSize.width === 192 && logoSize.height === 192,
  `${logoSize.width}x${logoSize.height}`,
);
// The mark is a black plate: the middle pixel is near-black, and the corner is
// transparent (the plate's own rounded corner, not a white square).
const mark = pngPixels(logo);
const pixel = (x, y) => {
  const at = (y * mark.width + x) * 4;
  return {
    r: mark.data[at],
    g: mark.data[at + 1],
    b: mark.data[at + 2],
    a: mark.data[at + 3],
  };
};
const plate = pixel(24, 96);
const corner = pixel(2, 2);
check(
  "the mark's plate is black",
  plate.r < 60 && plate.g < 60 && plate.b < 60 && plate.a > 200,
  JSON.stringify(plate),
);
check(
  "the mark's corners are transparent (the plate keeps its own rounded corners)",
  corner.a < 40,
  JSON.stringify(corner),
);
// The mark carries the owner's blue arrow, not the old amber.
let blue = 0;
let amber = 0;
for (let i = 0; i < mark.data.length; i += 4) {
  const r = mark.data[i];
  const g = mark.data[i + 1];
  const b = mark.data[i + 2];
  if (mark.data[i + 3] < 40) continue;
  if (b > 140 && b - r > 60 && g < 160) blue++;
  if (r > 190 && g > 120 && g < 200 && b < 90) amber++;
}
check("the mark keeps the owner's blue arrow", blue > 200, `${blue} blue pixels`);
check("the old amber mark is gone", amber === 0, `${amber} amber pixels`);

// The SVG favicon carries the very same PNG.
const iconSvg = read("web/public/icon.svg").toString();
const embedded = iconSvg.match(/base64,([A-Za-z0-9+/=]+)"/);
check("the favicon embeds the web logo", !!embedded);
if (embedded) {
  const same = Buffer.from(embedded[1], "base64");
  check(
    "the favicon's picture IS the web logo",
    same.length === logo.length && same.equals(logo),
    `${same.length} vs ${logo.length} bytes`,
  );
}

// The Android launcher, in every density, with the standard sizes.
const densities = {
  mdpi: { legacy: 48, foreground: 108, status: 24 },
  hdpi: { legacy: 72, foreground: 162, status: 36 },
  xhdpi: { legacy: 96, foreground: 216, status: 48 },
  xxhdpi: { legacy: 144, foreground: 324, status: 72 },
  xxxhdpi: { legacy: 192, foreground: 432, status: 96 },
};
let androidOk = true;
const androidDetail = [];
for (const [density, sizes] of Object.entries(densities)) {
  for (const [name, size] of [
    ["ic_launcher.png", sizes.legacy],
    ["ic_launcher_foreground.png", sizes.foreground],
    ["ic_launcher_round.png", sizes.legacy],
    ["ic_stat_kp.png", sizes.status],
  ]) {
    const path = `native-android/app/src/main/res/mipmap-${density}/${name}`;
    if (!existsSync(join(root, path))) {
      androidOk = false;
      androidDetail.push(`${path} is missing`);
      continue;
    }
    const got = pngSize(read(path));
    if (got.width !== size || got.height !== size) {
      androidOk = false;
      androidDetail.push(`${path} is ${got.width}x${got.height}, expected ${size}`);
    }
  }
}
check("every launcher and notification icon has its density's size", androidOk, androidDetail.join("; "));

// The in-app brand mark (the login header, the About screen, the
// notification's large icon) is one 512x512 file.
const brand = pngSize(read("native-android/app/src/main/res/drawable/icon_gold.png"));
check(
  "the in-app brand mark is 512x512",
  brand.width === 512 && brand.height === 512,
  `${brand.width}x${brand.height}`,
);

// The adaptive icon's background is the plate's black, so the launcher icon
// reads as the logo instead of an amber disc.
const background = read("native-android/app/src/main/res/values/ic_launcher_background.xml").toString();
check(
  "the adaptive icon's background is the plate's black",
  background.includes("#111113"),
  background.replace(/\s+/g, " ").slice(0, 120),
);
const adaptive = read("native-android/app/src/main/res/mipmap-anydpi-v26/ic_launcher.xml").toString();
check(
  "the adaptive icon draws the foreground over that background",
  adaptive.includes("@color/ic_launcher_background") && adaptive.includes("@mipmap/ic_launcher_foreground"),
);

// The generator that cut the assets is in the repo, so the next picture is a
// one-line change.
const generator = join(root, "scripts/make-brand-assets.py");
check("the brand-asset generator is in the repo", existsSync(generator));
if (existsSync(generator)) {
  const src = readFileSync(generator, "utf8");
  check(
    "the generator writes every mark and reads the owner's picture",
    src.includes("logo.png") &&
      src.includes("ic_launcher.png") &&
      src.includes("ic_launcher_foreground.png") &&
      src.includes("ic_launcher_round.png") &&
      src.includes("ic_stat_kp.png") &&
      src.includes("icon_gold.png") &&
      src.includes("photo.jpg"),
  );
}

// No stray build output in the brand folders.
const stray = readdirSync(join(root, "native-android/app/src/main/res/mipmap-xxxhdpi")).filter((f) =>
  f.endsWith(".webp"),
);
check("no stray .webp shadowing the PNG icons", stray.length === 0, stray.join(", "));

console.log(lines.join("\n"));
const broken = lines.filter((l) => l.includes("BROKEN")).length;
console.log(broken === 0 ? "\nALL OK" : `\n${broken} BROKEN`);
if (broken) process.exit(1);
